pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock oracle that returns a known price for version 1
        MockOracle mockOracle = new MockOracle();

        // Build ProductInfo with the mock oracle
        C.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "T";
        info.payoffDefinition.payoffType = 0;
        info.payoffDefinition.payoffDirection = 0;
        info.oracle = IOracleProvider(address(mockOracle));
        info.maintenance = UFixed18.wrap(0.1e18);
        info.fundingFee = UFixed18.wrap(0.01e18);
        info.makerFee = UFixed18.wrap(0.001e18);
        info.takerFee = UFixed18.wrap(0.002e18);
        info.positionFee = UFixed18.wrap(0.001e18);
        info.makerLimit = UFixed18.wrap(1000e18);
        info.utilizationCurve.minRate = PackedFixed18.wrap(0);
        info.utilizationCurve.maxRate = PackedFixed18.wrap(0);
        info.utilizationCurve.targetRate = PackedFixed18.wrap(0);
        info.utilizationCurve.targetUtilization = PackedUFixed18.wrap(0);

        // Initialize the product (msg.sender is this test contract)
        c.initialize(info);

        // Call atVersion(1) - reference should return price 5000e18, bug should revert
        bool success;
        try c.atVersion(1) {
            success = true;
        } catch {
            success = false;
        }

        // Reference succeeds (returns a value), bug reverts (because address(0) is not a contract)
        assertTrue(success);
    }
}

// Minimal mock oracle for testing
contract MockOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(5000e18));
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(5000e18));
    }

    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(5000e18));
    }
}

// Need these minimal interfaces/types for compilation
interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
}

type Fixed18 is int256;

type UFixed18 is uint256;
using UFixed18Lib for UFixed18 global;

library UFixed18Lib {
    function wrap(uint256 a) internal pure returns (UFixed18) { return UFixed18.wrap(a); }
}

type PackedFixed18 is int128;
type PackedUFixed18 is uint128;

struct PayoffDefinition {
    uint8 payoffType;
    uint8 payoffDirection;
    bytes30 data;
}

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

