pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a mock oracle that returns price 1000e18 for version 1
        vm.mockCall(
            address(0x1234),
            abi.encodeWithSignature("atVersion(uint256)", 1),
            abi.encode(1, block.timestamp, 1000e18)
        );
        vm.mockCall(
            address(0x1234),
            abi.encodeWithSignature("currentVersion()"),
            abi.encode(1, block.timestamp, 1000e18)
        );
        vm.mockCall(
            address(0x1234),
            abi.encodeWithSignature("sync()"),
            abi.encode(1, block.timestamp, 1000e18)
        );
        vm.store(address(c), bytes32(keccak256("equilibria.perennial.UPayoffProvider.oracle")), bytes32(uint256(uint160(address(0x1234)))));

        // Call atVersion(1) - should succeed on reference, revert on bug
        bool ok;
        try c.atVersion(1) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

