contract InvMutTest is Test {
    C c;

    function setUp() public {
        // Deploy mock oracle contract first
        MockOracle mockOracle = new MockOracle();

        // Deploy the product contract
        c = new C();

        // Create a ProductInfo with the mock oracle
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.NONE,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
                data: bytes30(0)
            }),
            oracle: IOracleProvider(address(mockOracle)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // Initialize the product
        c.initialize(info);
    }

    function testRegression_property() public {
        // In the reference, oracle() returns the MockOracle address
        // In the buggy version, oracle() returns 0x000000000000000000000000000000000000dEaD

        // Try calling atVersion(1) - reference succeeds, bug reverts
        bool ok = false;
        try c.atVersion(1) returns (IOracleProvider.OracleVersion memory) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference passes (ok=true), buggy fails (ok=false)
        assertTrue(ok);
    }
}

contract MockOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion({
            version: 1,
            timestamp: block.timestamp,
            price: Fixed18.wrap(1e18)
        });
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({
            version: 1,
            timestamp: block.timestamp,
            price: Fixed18.wrap(1e18)
        });
    }

    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion({
            version: 1,
            timestamp: block.timestamp,
            price: Fixed18.wrap(1e18)
        });
    }
}

interface IProduct {
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        IOracleProvider oracle;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }
    function initialize(ProductInfo calldata productInfo_) external;
    function oracle() external view returns (IOracleProvider);
    function atVersion(uint256 oracleVersion) external view returns (IOracleProvider.OracleVersion memory);
    function latestVersion() external view returns (uint256);
}

struct PayoffDefinition {
    uint8 payoffType;
    uint8 payoffDirection;
    bytes30 data;
}

library PayoffDefinitionLib {
    enum PayoffType { NONE, LINEAR, SIGNED }
    enum PayoffDirection { LONG, SHORT }
}

