// Mock oracle that returns empty version for atVersion(1)
contract MockOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

// Helper to bypass controller requirement for initialization
contract ControllerHelper {
    function initializeProduct(C product, C.ProductInfo memory info) external {
        product.initialize(info);
    }
}

