contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a concrete scenario: we need the product to have an oracle and be initialized
        // Since the contract uses msg.sender as controller in initialize, we deploy a mock controller
        // For simplicity, we directly call atVersion on an uninitialized contract will revert
        // Instead, we deploy with a minimal setup using foundry's cheatcodes to simulate
        // We create a simple oracle that returns a non-zero price
        // We use vm.mockCall to simulate the oracle response in the reference

        // Deploy a simple oracle that returns a fixed price
        address oracle = address(0x1234);
        // Set up oracle to return a version with price 100 ether
        bytes memory oracleCurrentVersion = abi.encode(1, block.timestamp, 100e18);
        bytes memory oracleAtVersion = abi.encode(1, block.timestamp, 100e18);

        // Initialize the product
        // For this, we need to call c.initialize with product info
        // But we don't have a real controller, so we use vm.prank to set msg.sender
        // We'll skip initialization and test atVersion directly with a mock

        // Since we cannot easily initialize, we test the difference using a different approach:
        // The bug is in currentVersion returning price 0 instead of the oracle's price
        // We can test this by calling atVersion which uses currentVersion (wrongly in bug)
        // We need a setup where atVersion returns a non-zero price in reference

        // We mock the oracle's currentVersion to return a non-zero price
        vm.mockCall(
            address(c),
            abi.encodeWithSelector(c.oracle.selector),
            abi.encode(oracle)
        );
        vm.mockCall(
            oracle,
            abi.encodeWithSelector(IOracleProvider.currentVersion.selector),
            abi.encode(IOracleProvider.OracleVersion({version: 1, timestamp: block.timestamp, price: Fixed18Lib.wrap(100e18)}))
        );
        vm.mockCall(
            oracle,
            abi.encodeWithSelector(IOracleProvider.atVersion.selector, 0),
            abi.encode(IOracleProvider.OracleVersion({version: 0, timestamp: block.timestamp, price: Fixed18Lib.wrap(0)}))
        );

        // Now call atVersion - in reference it returns oracle's price, in bug it returns 0
        IOracleProvider.OracleVersion memory v = c.atVersion(0);
        assertTrue(Fixed18.unwrap(v.price) == 0, "In reference, price should be 0 for version 0");
    }
}

