        address mockOracle = address(new MockOracle());

        // Construct ProductInfo with valid parameters
        // We need to provide a valid PayoffDefinition, oracle, and all UFixed18 parameters
        // For simplicity, use a known valid type
        C.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        // payoffDefinition: payoffType=0 (LINEAR), payoffDirection=0 (LONG), data = bytes30(0)
