        info.oracle = IOracleProvider(mockOracle);
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0.1e18);
        info.makerFee = UFixed18.wrap(0.01e18);
        info.takerFee = UFixed18.wrap(0.01e18);
        info.positionFee = UFixed18.wrap(0.001e18);
        info.makerLimit = UFixed18.wrap(1000e18);
        // JumpRateUtilizationCurve: minRate, maxRate, targetRate, targetUtilization packed
        info.utilizationCurve = C.JumpRateUtilizationCurve(
            PackedFixed18.wrap(int128(0)),
            PackedFixed18.wrap(int128(1e18)),
            PackedFixed18.wrap(int128(0.5e18)),
            PackedUFixed18.wrap(uint128(0.8e18))
        );

        // Initialize the product (needs to be called by the controller address)
        // Since the test deploys C with new C(), we need to simulate the controller
        // Using vm.startPrank with the address that will be set as controller
        // For simplicity, we can deploy a minimal controller mock and set it
        // Actually, the initialize function expects msg.sender to be the controller address
        // We'll prank as a dummy address and then call initialize directly
        vm.prank(address(0x1234));
        c.initialize(info);

        // Now call atVersion(0) - should succeed on reference, fail on mutant
        bool success;
        try c.atVersion(0) {
            success = true;
        } catch {
            success = false;
        }

        // The reference C should succeed (since atVersion calls controller() to get the oracle,
        // and the mock oracle returns a valid version). The mutant C will revert because
        // controller() returns address(0) and the call target is address(0).
        assertTrue(success, "atVersion should succeed on reference");
    }
}

// Minimal mock oracle that returns a fixed version
interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256) external view returns (OracleVersion memory);
}

contract MockOracle is IOracleProvider {
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

